import React, { useEffect, useState } from 'react';
import { Tabs } from 'expo-router';
import { Ionicons } from '@expo/vector-icons';
import * as WebBrowser from 'expo-web-browser';
import * as Google from 'expo-auth-session/providers/google';
import { View, StyleSheet, ActivityIndicator, Alert, AppState } from 'react-native';
import {
  onAuthStateChanged, signInWithEmailAndPassword, createUserWithEmailAndPassword,
    sendPasswordResetEmail, sendEmailVerification, signOut, GoogleAuthProvider, signInWithCredential, deleteUser, User,
    } from 'firebase/auth';
    import { doc, setDoc, getDoc, getDocs, query, where, updateDoc, onSnapshot, addDoc, collection, serverTimestamp } from 'firebase/firestore';
    import { auth, db } from '../config';
    import { ThemeProvider, useTheme, BRAND } from '../constants/theme';
    import { LangProvider, useLang } from '../constants/i18n';
    import { registerPushToken } from '../constants/push';
    import { ErrorBoundary } from '../constants/ErrorBoundary';
    import { AuthScreen } from '../constants/AuthScreen';

    WebBrowser.maybeCompleteAuthSession();
    const GOOGLE_WEB_CLIENT_ID = '506028452820-ogmgf2cshvpsd1b0639aa9m95d81t3u8.apps.googleusercontent.com';
    const GOOGLE_ANDROID_CLIENT_ID = '506028452820-aklgfkfhk631nhctjg1crorgl8a31qkf.apps.googleusercontent.com';

    const getFriendlyError = (code: string) => {
      if (code.includes('invalid-email')) return 'Please enter a valid email address.';
        if (code.includes('user-not-found') || code.includes('invalid-credential')) return 'Invalid email or password.';
          if (code.includes('wrong-password')) return 'Incorrect password. Try again.';
            if (code.includes('email-already-in-use')) return 'This email is already registered.';
              if (code.includes('weak-password')) return 'Password must be at least 6 characters.';
                return 'Something went wrong. Please try again.';
                };

                function AppContent() {
                  const { c } = useTheme();
                    const { t } = useLang();
                      const [user, setUser] = useState<User | null>(null);
                        const [loading, setLoading] = useState(true);
                          const [authLoading, setAuthLoading] = useState(false);
                            const [isLogin, setIsLogin] = useState(true);
                              const [email, setEmail] = useState('');
                                const [password, setPassword] = useState('');
                                  const [username, setUsername] = useState('');

                                    const [request, response, promptAsync] = Google.useIdTokenAuthRequest({
                                        androidClientId: GOOGLE_ANDROID_CLIENT_ID,
                                            webClientId: GOOGLE_WEB_CLIENT_ID,
                                                redirectUri: 'com.sudeep098.flevoraapp:/oauthredirect',
                                                  });

                                                    useEffect(() => {
                                                        if (response?.type === 'success' && response.params.id_token) {
                                                              const cred = GoogleAuthProvider.credential(response.params.id_token);
                                                                    signInWithCredential(auth, cred).then(async (res) => {
                                                                            const ref = doc(db, 'users', res.user.uid);
                                                                                    const snap = await getDoc(ref);
                                                                                            if (!snap.exists()) {
                                                                                                      let uname = (res.user.email?.split('@')[0] || 'user').toLowerCase().replace(/[^a-z0-9_]/g, '') || 'user';
                                                                                                                const taken = await getDocs(query(collection(db, 'users'), where('username', '==', uname)));
                                                                                                                          if (!taken.empty) uname = `${uname}${Math.floor(100 + Math.random() * 900)}`;
                                                                                                                                    await setDoc(ref, {
                                                                                                                                                uid: res.user.uid, email: res.user.email || '', username: uname,
                                                                                                                                                            fullName: res.user.displayName || uname, bio: '', website: '', avatar: res.user.photoURL || '',
                                                                                                                                                                        role: 'user', status: 'active', verified: false, isPrivate: false, isOnline: true, lastSeen: serverTimestamp(),
                                                                                                                                                                                    followers: [], following: [], savedPosts: [], blockedUsers: [], createdAt: serverTimestamp(),
                                                                                                                                                                                              });
                                                                                                                                                                                                      }
                                                                                                                                                                                                            }).catch(() => Alert.alert('Google Sign-In Failed', 'Could not sign in with Google.'));
                                                                                                                                                                                                                }
                                                                                                                                                                                                                  }, [response]);

                                                                                                                                                                                                                    useEffect(() => {
                                                                                                                                                                                                                        const unsub = onAuthStateChanged(auth, (u) => {
                                                                                                                                                                                                                              setUser(u);
                                                                                                                                                                                                                                    setLoading(false);
                                                                                                                                                                                                                                          if (u) {
                                                                                                                                                                                                                                                  updateDoc(doc(db, 'users', u.uid), { isOnline: true, lastSeen: serverTimestamp() }).catch(() => {});
                                                                                                                                                                                                                                                          registerPushToken(u.uid);
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                        const sub = AppState.addEventListener('change', (state) => {
                                                                                                                                                                                                                                                                              if (auth.currentUser) {
                                                                                                                                                                                                                                                                                      updateDoc(doc(db, 'users', auth.currentUser.uid), { isOnline: state === 'active', lastSeen: serverTimestamp() }).catch(() => {});
                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                    return () => { unsub(); sub.remove(); };
                                                                                                                                                                                                                                                                                                      }, []);

                                                                                                                                                                                                                                                                                                        useEffect(() => {
                                                                                                                                                                                                                                                                                                            if (!user) return;
                                                                                                                                                                                                                                                                                                                return onSnapshot(doc(db, 'users', user.uid), (s) => {
                                                                                                                                                                                                                                                                                                                      if (!s.exists()) return;
                                                                                                                                                                                                                                                                                                                            const st = s.data().status;
                                                                                                                                                                                                                                                                                                                                  if (st === 'suspended') {
                                                                                                                                                                                                                                                                                                                                          Alert.alert('Account Suspended', 'Your account is suspended. Submit an appeal?', [
                                                                                                                                                                                                                                                                                                                                                    { text: 'Log Out', style: 'cancel', onPress: () => signOut(auth) },
                                                                                                                                                                                                                                                                                                                                                              {
                                                                                                                                                                                                                                                                                                                                                                          text: 'Submit Appeal',
                                                                                                                                                                                                                                                                                                                                                                                      onPress: async () => {
                                                                                                                                                                                                                                                                                                                                                                                                    await addDoc(collection(db, 'appeals'), {
                                                                                                                                                                                                                                                                                                                                                                                                                    uid: user.uid, email: user.email || '', message: 'Requesting account review.', status: 'pending', createdAt: serverTimestamp(),
                                                                                                                                                                                                                                                                                                                                                                                                                                  }).catch(() => {});
                                                                                                                                                                                                                                                                                                                                                                                                                                                await signOut(auth);
                                                                                                                                                                                                                                                                                                                                                                                                                                                              Alert.alert('Appeal Sent', 'An admin will review your account.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else if (st === 'deactivated') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          updateDoc(doc(db, 'users', user.uid), { status: 'active' }).catch(() => {});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }, [user]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const handleAuth = async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!email.trim() || !password || (!isLogin && !username.trim())) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return Alert.alert('Missing Info', 'Please fill in all fields.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setAuthLoading(true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (isLogin) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await signInWithEmailAndPassword(auth, email.trim(), password);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const uname = username.trim().toLowerCase().replace(/[^a-z0-9_]/g, '');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (uname.length < 3) return Alert.alert('Invalid Username', 'Use at least 3 letters/numbers.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const res = await createUserWithEmailAndPassword(auth, email.trim(), password);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const existing = await getDocs(query(collection(db, 'users'), where('username', '==', uname)));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!existing.empty) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await deleteUser(res.user);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return Alert.alert('Username Taken', `@${uname} is already in use. Choose another.`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await setDoc(doc(db, 'users', res.user.uid), {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        uid: res.user.uid, email: email.trim().toLowerCase(), username: uname,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fullName: username.trim(), bio: '', website: '', avatar: '', role: 'user',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            status: 'active', verified: false, isPrivate: false, isOnline: true, lastSeen: serverTimestamp(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      followers: [], following: [], savedPosts: [], blockedUsers: [], createdAt: serverTimestamp(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      sendEmailVerification(res.user).catch(() => {});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Alert.alert('Verify Email', 'Account created! A verification link has been sent to your email.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (e: any) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Alert.alert('Auth Error', getFriendlyError(e.code || ''));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } finally {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setAuthLoading(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const handleForgot = async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!email.trim()) return Alert.alert('Reset Password', 'Enter your email first.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await sendPasswordResetEmail(auth, email.trim());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Alert.alert('Email Sent', 'Check your inbox for the password reset link.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (e: any) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Alert.alert('Error', getFriendlyError(e.code || ''));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (loading) return <View style={[styles.center, { backgroundColor: c.background }]}><ActivityIndicator size="large" color={BRAND} /></View>;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!user) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <AuthScreen
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          isLogin={isLogin} setIsLogin={setIsLogin} username={username} setUsername={setUsername}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  email={email} setEmail={setEmail} password={password} setPassword={setPassword}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          authLoading={authLoading} googleReady={!!request}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onAuth={handleAuth} onGoogle={() => promptAsync()} onForgot={handleForgot}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Tabs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          backBehavior="history"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                screenOptions={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        headerShown: false, tabBarActiveTintColor: BRAND, tabBarInactiveTintColor: c.muted,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tabBarStyle: { backgroundColor: c.background, borderTopColor: c.border, height: 58, paddingBottom: 6 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Tabs.Screen name="index" options={{ title: t.home, tabBarIcon: ({ color, size }) => <Ionicons name="home" size={size} color={color as string} /> }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Tabs.Screen name="explore" options={{ title: t.explore, tabBarIcon: ({ color, size }) => <Ionicons name="search" size={size} color={color as string} /> }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Tabs.Screen name="upload" options={{ title: t.create, tabBarIcon: ({ color, size }) => <Ionicons name="add-circle" size={size + 4} color={color as string} /> }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Tabs.Screen name="reels" options={{ title: t.reels, tabBarIcon: ({ color, size }) => <Ionicons name="play-circle" size={size} color={color as string} /> }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Tabs.Screen name="profile" options={{ title: t.profile, tabBarIcon: ({ color, size }) => <Ionicons name="person" size={size} color={color as string} /> }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Tabs.Screen name="user/[id]" options={{ href: null }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Tabs.Screen name="notification" options={{ href: null }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Tabs.Screen name="messages" options={{ href: null }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Tabs.Screen name="settings" options={{ href: null }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </Tabs>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      export default function RootLayout() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return <ErrorBoundary><ThemeProvider><LangProvider><AppContent /></LangProvider></ThemeProvider></ErrorBoundary>;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const styles = StyleSheet.create({ center: { flex: 1, justifyContent: 'center', alignItems: 'center' } });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        